WITH exploded AS (SELECT id, plan, currency, val FROM price_tiers LATERAL VIEW EXPLODE(tier_limits) e AS val) SELECT CASE WHEN val >= 84 THEN 'PREMIUM' ELSE 'STANDARD' END AS val_tier, currency, ROUND(AVG(val), 2) AS avg_val, SORT_ARRAY(COLLECT_SET(plan)) AS plan_list, PERCENTILE_APPROX(val, 0.5) AS val_p50, SIZE(COLLECT_SET(plan)) AS num_plans, ROUND(SUM(val) / NULLIF(COUNT(CASE WHEN currency = 'THB' THEN 1 END), 0), 2) AS val_per_thb, SUM(CASE WHEN currency = 'USD' THEN val ELSE 0 END) AS usd_val, DENSE_RANK() OVER (PARTITION BY CASE WHEN val >= 84 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY ROUND(AVG(val), 2) DESC) AS avg_val_dense_rank FROM exploded GROUP BY CASE WHEN val >= 84 THEN 'PREMIUM' ELSE 'STANDARD' END, currency ORDER BY val_per_thb DESC NULLS FIRST
